window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-06b4142720f90757"]={"versions": [{"id": "FIG-06b4142720f90757", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockschaltbild der AUTOSAR-Classic-Platform-Basissoftware (BSW-Schichtenarchitektur). Dargestellt ist die Einbettung des XCP-Moduls in die BSW-Schichten (Communication Services / System Services) oberhalb der Hardware-Abstraktionsschicht sowie dessen Einordnung parallel zum klassischen AUTOSAR-Kommunikationsstack (COM, DCM, IPDUM, PDU-Router).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Schichten (von oben nach unten):</li>\n<li>Runtime Environment (<code>RTE</code>, orange).</li>\n<li>Services Layer (blau) mit zwei Hauptbereichen:</li>\n<li>Flankierend: Betriebssystem (<code>OS</code>), horizontal gekoppelt mit dem XCP-Protokoll.</li>\n<li>XCP-Modul (dick umrandet): Bestehend aus dem Protokollkern <code>XCP Protocol</code> und den drei busspezifischen Transportschichten <code>XCPonCan</code>, <code>XCPonFr</code> sowie <code>XCPonEth</code>.</li>\n<li>Standard-Kommunikationsstack: <code>IPDUM</code>, <code>COM</code>, <code>DCM</code> (oben), zentraler <code>PDUR</code> (PDU Router) sowie darunter Transportprotokoll (<code>TP</code>) und Netzwerkmanagement (<code>NM</code>).</li>\n<li>Communication HW Abstraction (grün) mit <code>Bus Interfac(s)</code>.</li>\n<li>Communication Drivers (rot) mit <code>Bus Driver(s)</code>.</li>\n<li>Schnittstellen und Pfade:</li>\n<li>Schwarze Doppelpfeile (Datenpfad / Signale & PDUs): Bidirektionale Verbindungen zwischen RTE <-> COM; COM, IPDUM, DCM <-> PDUR; PDUR <-> TP, NM; PDUR, TP, NM <-> Bus Interfac(s); XCPonCan, XCPonFr, XCPonEth <-> Bus Interfac(s); Bus Interfac(s) <-> Bus Driver(s).</li>\n<li>Orange Doppelpfeile (Kontrollpfad): Verbindung zwischen OS <-> XCP Protocol sowie zwischen XCPonFr <-> Bus Interfac(s) (FlexRay Interface).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Datenpfad (schwarze Pfeile):</li>\n<li>Kalibrier- und Messdaten (XCP-PDUs) werden im XCP-Modul über <code>XCPonCan</code>, <code>XCPonFr</code> oder <code>XCPonEth</code> direkt an die jeweiligen <code>Bus Interfac(s)</code> übergeben, unter Umgehung des AUTOSAR PDU-Routers (<code>PDUR</code>).</li>\n<li>Reguläre Anwendungs- und Diagnosedaten fließen separat über RTE, COM, DCM und PDUR an TP bzw. direkt an die Bus Interfaces.</li>\n<li>Kontrollpfad (orange Pfeile):</li>\n<li>Das Betriebssystem (<code>OS</code>) steuert und synchronisiert das <code>XCP Protocol</code> (Triggerung von Tasks, DAQ-Listen und Ereignissen).</li>\n<li><code>XCPonFr</code> steuert über den Kontrollpfad das FlexRay Interface direkt (z. B. Puffer- und Slot-Zuweisung, Synchronisation auf den FlexRay-Zyklus).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Anforderungen:</li>\n<li>[SWS_Xcp_00701]: Das AUTOSAR XCP-Modul muss bei CAN und FlexRay oberhalb der busspezifischen Schnittstellen angeordnet sein. Bei Ethernet fordert die Spezifikation die Anordnung oberhalb des Socket Adaptors (<code>SoAd</code>).</li>\n<li>[SWS_Xcp_00702]: Verortung der Busschnittstellen in der Abstraktionsschicht.</li>\n<li>Architektur-Inkonsistenz im Diagramm: Obwohl [SWS_Xcp_00701] explizit <code>SoAd</code> für Ethernet nennt, ist im vorliegenden Schaubild (R4.1.3) kein <code>SoAd</code> dargestellt; <code>XCPonEth</code> bindet grafisch direkt an <code>Bus Interfac(s)</code> an.</li>\n<li>Entwickler-Hinweis: Für FlexRay ist zwingend die Doppelverbindung aus Datenpfad und Kontrollpfad zum FlexRay Interface zu implementieren.</li>\n</ul>"}, {"id": "FIG-c7690a42d9a302a7", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Blockschaltbild der AUTOSAR-Classic-Platform-Basissoftware (BSW-Schichtenarchitektur). Dargestellt ist die Einbettung des XCP-Moduls in die BSW-Schichten (Communication Services / System Services) oberhalb der Hardware-Abstraktionsschicht sowie dessen Einordnung parallel zum klassischen AUTOSAR-Kommunikationsstack (COM, DCM, IPDUM, PDU-Router).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Schichten (von oben nach unten):</li>\n<li>Runtime Environment (<code>RTE</code>, orange).</li>\n<li>Services Layer (blau):</li>\n<li>Flankierend: <code>OS</code> mit oranger Kontrollpfad-Anbindung an <code>XCP Protocol</code>.</li>\n<li>XCP-Modul (dick umrandet): Der obere Bereich <code>XCP Protocol</code> ist in der Höhe reduziert. Darunter befinden sich die vertikal verlängerten Blöcke <code>XCPonCan</code> und <code>XCPonFr</code> sowie eine zweigeteilte Ethernet-Spalte: oben <code>SoAd</code> (Socket Adaptor), darunter <code>XCPonEth</code>.</li>\n<li>Standard-Kommunikationsstack: <code>IPDUM</code>, <code>COM</code>, <code>DCM</code>, <code>PDUR</code>, <code>TP</code>, <code>NM</code>.</li>\n<li>Communication HW Abstraction (grün) mit <code>Bus Interfac(s)</code>.</li>\n<li>Communication Drivers (rot) mit <code>Bus Driver(s)</code>.</li>\n<li>Schnittstellen und Pfade:</li>\n<li>Schwarze Doppelpfeile (Datenpfad): XCPonCan, XCPonFr und XCPonEth verbinden weiterhin nach unten zu <code>Bus Interfac(s)</code>. Zwischen DCM und PDUR ist der Verbindungsvektor an die linke Kante verschoben und weist einen Darstellungsfehler auf (horizontale Spitzen nach rechts statt vertikal bidirektional).</li>\n<li>Orange Doppelpfeile (Kontrollpfad): Unverändert zwischen OS <-> XCP Protocol sowie XCPonFr <-> Bus Interfac(s).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Datenpfad (schwarze Pfeile):</li>\n<li>XCP-PDUs über CAN und FlexRay laufen wie bisher von <code>XCPonCan</code> und <code>XCPonFr</code> direkt in die <code>Bus Interfac(s)</code>.</li>\n<li>Der Ethernet-Übertragungsweg bindet nun visuell den Socket Adaptor (<code>SoAd</code>) innerhalb des XCP-Blocks ein (oberhalb von <code>XCPonEth</code>), während die Kopplung zu den <code>Bus Interfac(s)</code> weiterhin von <code>XCPonEth</code> ausgeht.</li>\n<li>Standard-Kommunikationsdaten laufen unverändert über RTE, COM, DCM und PDUR.</li>\n<li>Kontrollpfad (orange Pfeile):</li>\n<li>Unveränderte Ereignis- und Zyklustriggerung des XCP-Protokolls durch das OS.</li>\n<li>Direkte Steuerungsinteraktion von <code>XCPonFr</code> mit dem FlexRay Interface.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Relevanz:</li>\n<li>Umsetzung von [SWS_Xcp_00701]: <code>SoAd</code> wurde im Diagramm ergänzt, um der Anforderung („In case of Ethernet, the AUTOSAR XCP module shall be located above the Socket Adaptor“) Rechnung zu tragen.</li>\n<li>Spezifikations- und Darstellungsfehler:</li>\n<li>Verkehrte Schichtung im Diagramm: Visuell liegt <code>SoAd</code> innerhalb des XCP-Moduls oberhalb von <code>XCPonEth</code>, und <code>XCPonEth</code> dockt an <code>Bus Interfac(s)</code> an. Nach der normativen AUTOSAR-Architektur muss <code>XCPonEth</code> das XCP-Modul nach unten abschließen und auf <code>SoAd</code> aufsetzen, welcher wiederum auf <code>TcpIp</code> / <code>EthIf</code> aufbaut.</li>\n<li>Zeichnungsfehler bei DCM-Anbindung: Der Pfeil zwischen DCM und PDUR ist an die Blockkante verschoben und besitzt horizontal nach rechts zeigende Spitzen; implementierungsseitig bleibt die Schnittstelle ein standardmäßiger vertikaler, bidirektionaler PDU-Austausch.</li>\n</ul>"}], "trans": [{"from": "FIG-06b4142720f90757", "to": "FIG-c7690a42d9a302a7", "fr": "R4.1.3", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>XCP-Modul (Ethernet-Zweig)</code>: Aufnahme des Moduls <code>SoAd</code> (Socket Adaptor) in die rechte Spalte oberhalb von <code>XCPonEth</code> bei gleichzeitiger Verringerung der Höhe des Blocks <code>XCP Protocol</code> und Anhebung der horizontalen Trennlinie.</li>\n<li><code>DCM / PDUR</code>: Verbindungsvektor an die linke Kante von DCM verschoben und zeichnerisch fehlerhaft mit zwei nach rechts weisenden Pfeilspitzen dargestellt.</li>\n</ul>"}]};
